/* ===================== BÀI 47 · PWM phần mềm và driver động cơ ===================== */
/* Bài 47 · PWM phần mềm và driver động cơ (AMTS-EMB-001-M12-L03, MC51-047) — sinh bởi tools/author/mcu8051/l47.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 (thiết bị ảo đo lường/điều khiển tải: platform/js/56-mcu51-ana.js) và bài tập chấm tự động. Lời giải không nằm ở đây. */
const P47=[{"label":"Ví dụ: PWM vòng trễ, duty 25 %","code":"; PWM bằng vòng trễ: duty 25 %, 4 chu kỳ PWM\n        ORG     0000H\n        CLR     P2.0                    ; EN = 0 trước (sau reset P2 = FFH)\n        CLR     P2.2                    ; IN2 = 0\n        SETB    P2.1                    ; IN1 = 1: quay thuận\n        MOV     R7,#4                   ; số chu kỳ PWM\nLAP:    SETB    P2.0                    ; EN = 1\n        MOV     R6,#11\n        DJNZ    R6,$                    ; 11 x 2 = 22 chu kỳ\n        CLR     P2.0                    ; EN = 0\n        MOV     R6,#34\n        DJNZ    R6,$                    ; 34 x 2 = 68 chu kỳ\n        DJNZ    R7,LAP\n        SJMP    $\n        END\n","note":"Lệnh đầu đặt EN = 0 vì sau reset P2 = FFH. Mỗi chu kỳ PWM 96 chu kỳ máy, mức cao 24 → duty 25 %, ≈ 10,4 kHz; bảng thiết bị báo jitter 0. Đổi #11 và #34 (giữ tổng 45) để đổi duty mà không đổi tần số.","dev":{"motor":true},"fosc":12000000},{"label":"Ví dụ: PWM 4 bit bằng bộ đếm và so sánh","code":"; PWM 4 bit bằng bộ đếm và phép so sánh: duty = 4/16\n        ORG     0000H\n        CLR     P2.0\n        CLR     P2.2\n        SETB    P2.1                    ; quay thuận\n        MOV     R4,#4                   ; duty: 4 trên 16 mức\n        MOV     R5,#0                   ; bộ đếm tick\n        MOV     R7,#48                  ; 48 tick = 3 chu kỳ PWM\nTICK:   MOV     A,R5\n        ANL     A,#0FH                  ; đếm 0..15\n        CLR     C\n        SUBB    A,R4                    ; C = 1 khi đếm < duty\n        MOV     P2.0,C                  ; EN = C\n        INC     R5\n        DJNZ    R7,TICK                 ; mỗi tick 9 chu kỳ\n        SJMP    $\n        END\n","note":"Mỗi tick 9 chu kỳ: so sánh đếm (4 bit thấp của R5) với duty R4 = 4. Chu kỳ PWM 16 × 9 = 144 chu kỳ máy, mức cao 36 (25 %). Thử R4 = 0 (EN luôn 0) và R4 = 16 (EN luôn 1).","dev":{"motor":true},"fosc":12000000},{"label":"Ví dụ: Đổi chiều qua trạng thái dừng","code":"; Đổi chiều qua trạng thái dừng: thuận -> dừng -> ngược\n        ORG     0000H\n        CLR     P2.0                    ; EN = 0 (sau reset P2 = FFH)\n        SETB    P2.1\n        CLR     P2.2                    ; IN1 = 1, IN2 = 0: thuận\n        SETB    P2.0                    ; EN = 1 (duty 100 %)\n        ACALL   CHO                     ; chạy khoảng 5 ms\n        CLR     P2.1                    ; IN1 = IN2 = 0: dừng\n        ACALL   CHO                     ; chờ động cơ chậm lại\n        SETB    P2.2                    ; IN1 = 0, IN2 = 1: ngược\n        ACALL   CHO\n        SJMP    $\nCHO:    MOV     R5,#10                  ; 10 x 503 + 1 + 2 = 5 033 chu kỳ\nC1:     MOV     R6,#250\n        DJNZ    R6,$\n        DJNZ    R5,C1\n        RET\n        END\n","note":"Thuận 5 ms → dừng (IN1 = IN2 = 0) 5 ms → ngược 5 ms. Xem tốc độ tương đối giảm về gần 0 trước khi đổi chiều (hằng số thời gian 5 ms, giả định). Cuối cùng P2 = FDH: EN = 1, IN1 = 0, IN2 = 1.","dev":{"motor":{"tau_ms":5}},"fosc":12000000,"speed":"real"},{"label":"Ví dụ: PWM bằng ngắt Timer 0, 10 mức","code":"; PWM bằng ngắt Timer 0: tick 100 chu kỳ, 10 mức, duty 3/10\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH                   ; vector ngắt Timer 0\n        PUSH    PSW\n        PUSH    ACC\n        MOV     A,30H                   ; đếm tick 0..9\n        CLR     C\n        SUBB    A,31H                   ; C = 1 khi đếm < duty\n        MOV     P2.0,C                  ; EN\n        INC     30H\n        MOV     A,30H\n        CJNE    A,#10,RA\n        MOV     30H,#0                  ; hết 10 tick: chu kỳ PWM mới\n        INC     32H                     ; số chu kỳ PWM đã xong\nRA:     POP     ACC\n        POP     PSW\n        RETI\nMAIN:   CLR     P2.0\n        CLR     P2.2\n        SETB    P2.1                    ; quay thuận\n        MOV     30H,#0\n        MOV     31H,#3                  ; duty 3/10 = 30 %\n        MOV     32H,#0\n        MOV     TMOD,#02H               ; Timer 0 chế độ 2 (tự nạp)\n        MOV     TH0,#9CH                ; 256 - 100: tràn mỗi 100 chu kỳ\n        MOV     TL0,#9CH\n        SETB    ET0\n        SETB    EA\n        SETB    TR0\nDOI:    MOV     A,32H\n        CJNE    A,#4,DOI                ; chờ đủ 4 chu kỳ PWM\n        CLR     TR0\n        CLR     EA\n        SJMP    $\n        END\n","note":"Ngắt Timer 0 mỗi 100 chu kỳ; 10 tick một chu kỳ PWM 1 kHz, duty 3/10. Chương trình ngắt 21 chu kỳ (24 ở tick cuối): tải CPU ≈ 21 %. Các chu kỳ đo được 999, 1 000, 1 001; bảng thiết bị bỏ chu kỳ đầu nên báo jitter 1 chu kỳ máy.","dev":{"motor":true},"fosc":12000000,"speed":"real"},{"label":"Bẫy: So sánh ≤ làm duty 0 vẫn có xung","code":"; Bẫy: so sánh \"đếm <= duty\" nên duty = 0 vẫn có xung\n        ORG     0000H\n        CLR     P2.0\n        CLR     P2.2\n        SETB    P2.1\n        MOV     R4,#0                   ; duty = 0: muốn động cơ đứng yên\n        MOV     R5,#0\n        MOV     R7,#48\nTICK:   MOV     A,R5\n        ANL     A,#0FH\n        MOV     R3,A                    ; R3 = đếm 0..15\n        MOV     A,R4\n        CLR     C\n        SUBB    A,R3                    ; duty - đếm: C = 1 khi duty < đếm\n        CPL     C                       ; C = 1 khi đếm <= duty: SAI\n        MOV     P2.0,C\n        INC     R5\n        DJNZ    R7,TICK                 ; mỗi tick 12 chu kỳ\n        SJMP    $\n        END\n","note":"Duty = 0 nhưng so sánh “đếm ≤ duty” bật EN ở tick 0 của mỗi chu kỳ: mức cao 12 trên 192 chu kỳ máy (6,25 %). Động cơ không bao giờ dừng hẳn. Sửa: C = 1 khi đếm < duty (SUBB A,R4 với A = đếm, như ví dụ 2).","dev":{"motor":true},"fosc":12000000}];
const sim47=makeSim51(document.getElementById("m51-l47"),{id:"s47",presets:P47,ram:256});
makeEx51(document.getElementById("ex-l47"),"l47",[{"t":"Lệnh cho driver cầu H","d":"<p>Driver cầu H nối EN = <code>P2.0<\/code>, IN1 = <code>P2.1<\/code>, IN2 = <code>P2.2<\/code>; các chân P2.3…P2.7 nối mạch khác và phải <b>giữ nguyên mức 1<\/b>. Ô <code>30H<\/code> chứa lệnh: <code>0<\/code> = dừng (EN = IN1 = IN2 = 0), <code>1<\/code> = quay thuận (EN = 1, IN1 = 1, IN2 = 0), <code>2<\/code> = quay ngược (EN = 1, IN1 = 0, IN2 = 1). Mọi giá trị khác là lệnh hỏng: phải <b>dừng<\/b>. Viết chương trình đặt ba chân theo lệnh.<\/p><p>Ví dụ: <code>30H = 1<\/code> → <code>P2 = FBH<\/code>; <code>30H = 7<\/code> → <code>P2 = F8H<\/code>.<\/p>","start":"; Lệnh ở 30H -> chân EN (P2.0), IN1 (P2.1), IN2 (P2.2)\n        ORG     0000H\n        MOV     A,30H\n        CJNE    A,#1,KHAC1\n        MOV     P2,#03H                 ; thuận: EN = 1, IN1 = 1\n        SJMP    XONG\nKHAC1:  CJNE    A,#2,XONG\n        MOV     P2,#05H                 ; ngược: EN = 1, IN2 = 1\nXONG:   SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":1}},"expect":{"iram":{"0x30":1},"ports":{"P2":251}}},{"setup":{"iram":{"0x30":2}},"expect":{"iram":{"0x30":2},"ports":{"P2":253}}},{"setup":{"iram":{"0x30":0}},"expect":{"iram":{"0x30":0},"ports":{"P2":248}}},{"setup":{"iram":{"0x30":3}},"expect":{"iram":{"0x30":3},"ports":{"P2":248}}},{"setup":{"iram":{"0x30":255}},"expect":{"iram":{"0x30":255},"ports":{"P2":248}}},{"setup":{"iram":{"0x30":129}},"expect":{"iram":{"0x30":129},"ports":{"P2":248}}},{"setup":{"iram":{"0x30":1},"pins":{"P2":223}},"expect":{"iram":{"0x30":1},"ports":{"P2":251}}}]},"hints":["Code mẫu ghi cả byte MOV P2,#03H nên kéo P2.3…P2.7 xuống 0, và không xử lý lệnh 0 hay lệnh hỏng.","Chọn trước 3 bit mới (R2 = 03H, 05H hoặc 00H), rồi sửa ngay trên cổng bằng lệnh đọc–sửa–ghi: ANL P2,#0F8H rồi MOV A,R2 và ORL P2,A. ANL/ORL trên cổng đọc CHỐT; MOV A,P2 đọc CHÂN, nên nếu mạch khác đang kéo một chân P2.3…P2.7 xuống 0 thì ghi lại sẽ xóa luôn bit chốt đó (bộ thử 7).","Nhánh mặc định (không phải 1, không phải 2) phải là dừng: thiết bị nhận lệnh hỏng không được tự quay."],"why":"Đọc–sửa–ghi chỉ 3 bit thấp giữ nguyên các chân khác trên cùng cổng; dùng ANL/ORL trực tiếp trên P2 vì các lệnh này đọc chốt, còn MOV A,P2 đọc chân (Chương 6) và có thể xóa nhầm bit khi mạch ngoài đang kéo chân xuống 0. Lệnh không hợp lệ đưa về trạng thái an toàn (dừng) là quy tắc thiết kế cho mọi tải công suất: lỗi phần mềm không được làm động cơ quay."},{"t":"Khởi động mềm: tiến dần tới duty đích","d":"<p>Đổi duty đột ngột làm dòng khởi động lớn. Mỗi chu kỳ PWM, chương trình đưa duty hiện tại <code>30H<\/code> tiến về duty đích <code>31H<\/code> một bước tối đa <code>32H<\/code> (1…255): nếu nhỏ hơn đích thì cộng bước, lớn hơn thì trừ bước, nhưng <b>không bao giờ vượt qua đích<\/b> (kể cả khi phép cộng tràn quá 255 hay phép trừ xuống dưới 0); bằng đích thì giữ nguyên. Ghi kết quả vào <code>30H<\/code>; 31H, 32H giữ nguyên.<\/p><p>Ví dụ: 30H = 78H, 31H = 80H, 32H = 10H → <code>30H = 80H<\/code>; 30H = F0H, 31H = FFH, 32H = 20H → <code>30H = FFH<\/code>.<\/p>","start":"; Khởi động mềm: đưa duty 30H về đích 31H, mỗi lần tối đa 32H\n        ORG     0000H\n        MOV     A,30H\n        CJNE    A,31H,KHAC\n        SJMP    XONG                    ; đã bằng đích\nKHAC:   JNC     GIAM\n        ADD     A,32H                   ; tăng một bước\n        SJMP    GHI\nGIAM:   CLR     C\n        SUBB    A,32H                   ; giảm một bước\nGHI:    MOV     30H,A\nXONG:   SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":32,"0x31":128,"0x32":16}},"expect":{"iram":{"0x30":48,"0x31":128,"0x32":16}}},{"setup":{"iram":{"0x30":120,"0x31":128,"0x32":16}},"expect":{"iram":{"0x30":128,"0x31":128,"0x32":16}}},{"setup":{"iram":{"0x30":240,"0x31":255,"0x32":32}},"expect":{"iram":{"0x30":255,"0x31":255,"0x32":32}}},{"setup":{"iram":{"0x30":128,"0x31":32,"0x32":16}},"expect":{"iram":{"0x30":112,"0x31":32,"0x32":16}}},{"setup":{"iram":{"0x30":16,"0x31":0,"0x32":32}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":32}}},{"setup":{"iram":{"0x30":69,"0x31":64,"0x32":10}},"expect":{"iram":{"0x30":64,"0x31":64,"0x32":10}}},{"setup":{"iram":{"0x30":85,"0x31":85,"0x32":8}},"expect":{"iram":{"0x30":85,"0x31":85,"0x32":8}}}]},"hints":["CJNE A,31H,… cho C = 1 khi hiện tại &lt; đích: tăng; C = 0 (và khác nhau): giảm.","Sau ADD, CY = 1 nghĩa là tổng thật đã quá 255 nên chắc chắn quá đích; sau SUBB, CY = 1 nghĩa là đã xuống dưới 0.","Không tràn thì so kết quả với đích lần nữa (CJNE A,31H,$+3 chỉ để lấy cờ C); quá đích thì lấy đúng giá trị đích."],"why":"Bộ giới hạn tốc độ thay đổi (rate limiter) làm duty đi theo đường dốc. Có hai cách vượt đích phải chặn: vượt bình thường (78H + 10H = 88H &gt; 80H) và vượt do tràn 8 bit (F0H + 20H = 110H, byte thấp 10H nhỏ hơn đích nên nếu không xét CY sẽ tưởng chưa tới)."},{"t":"Một tick PWM 8 kênh không quá 40 chu kỳ","d":"<p>Phần mềm PWM 8 kênh chạy trong ngắt timer: mỗi tick, kênh i (i = 0…7) bật khi <b>đếm &lt; duty kênh i<\/b>. Duty các kênh ở <code>30H<\/code>…<code>37H<\/code>, bộ đếm tick ở <code>38H<\/code>. Viết <b>một tick<\/b>: ghi bit i của <code>P1<\/code> = 1 khi [38H] &lt; [30H + i] (so sánh không dấu), rồi tăng <code>38H<\/code> (FFH quay về 00H). Các ô duty giữ nguyên; ô <code>20H<\/code>…<code>2FH<\/code> được dùng tự do. Code mẫu đúng nhưng mất khoảng 80 chu kỳ — với tick 100 chu kỳ thì CPU gần như không còn thời gian. Hãy viết lại để chạy không quá <b>40 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>), mã không quá <b>52 byte<\/b>.<\/p><p>Ví dụ: đếm 00H, duty 00H, 01H, 10H, 40H, 80H, C0H, FFH, 00H → <code>P1 = 7EH<\/code>, <code>38H = 01H<\/code>.<\/p>","start":"; Một tick PWM 8 kênh: bit i của P1 = 1 khi đếm < duty kênh i\n; Đúng nhưng chậm: vòng lặp 8 lần, gom bit bằng RLC.\n        ORG     0000H\n        MOV     R0,#37H                 ; duty kênh 7 trước\n        MOV     R2,#0\n        MOV     R7,#8\nLAP:    MOV     A,38H                   ; đếm\n        CLR     C\n        SUBB    A,@R0                   ; C = 1 khi đếm < duty\n        MOV     A,R2\n        RLC     A                       ; đẩy bit mới vào bên phải\n        MOV     R2,A\n        DEC     R0\n        DJNZ    R7,LAP\n        MOV     P1,R2\n        INC     38H                     ; tick kế tiếp\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":0,"0x31":1,"0x32":16,"0x33":64,"0x34":128,"0x35":192,"0x36":255,"0x37":0,"0x38":0}},"expect":{"iram":{"0x30":0,"0x31":1,"0x32":16,"0x33":64,"0x34":128,"0x35":192,"0x36":255,"0x37":0,"0x38":1},"ports":{"P1":126}}},{"setup":{"iram":{"0x30":0,"0x31":1,"0x32":16,"0x33":64,"0x34":128,"0x35":192,"0x36":255,"0x37":65,"0x38":64}},"expect":{"iram":{"0x30":0,"0x31":1,"0x32":16,"0x33":64,"0x34":128,"0x35":192,"0x36":255,"0x37":65,"0x38":65},"ports":{"P1":240}}},{"setup":{"iram":{"0x30":255,"0x31":255,"0x32":255,"0x33":255,"0x34":255,"0x35":255,"0x36":255,"0x37":255,"0x38":255}},"expect":{"iram":{"0x30":255,"0x31":255,"0x32":255,"0x33":255,"0x34":255,"0x35":255,"0x36":255,"0x37":255,"0x38":0},"ports":{"P1":0}}},{"setup":{"iram":{"0x30":128,"0x31":127,"0x32":128,"0x33":127,"0x34":128,"0x35":127,"0x36":128,"0x37":127,"0x38":127}},"expect":{"iram":{"0x30":128,"0x31":127,"0x32":128,"0x33":127,"0x34":128,"0x35":127,"0x36":128,"0x37":127,"0x38":128},"ports":{"P1":85}}},{"setup":{"iram":{"0x30":5,"0x31":21,"0x32":37,"0x33":53,"0x34":69,"0x35":85,"0x36":101,"0x37":117,"0x38":16}},"expect":{"iram":{"0x30":5,"0x31":21,"0x32":37,"0x33":53,"0x34":69,"0x35":85,"0x36":101,"0x37":117,"0x38":17},"ports":{"P1":254}}},{"setup":{"iram":{"0x30":201,"0x31":200,"0x32":199,"0x33":255,"0x34":0,"0x35":201,"0x36":1,"0x37":254,"0x38":200}},"expect":{"iram":{"0x30":201,"0x31":200,"0x32":199,"0x33":255,"0x34":0,"0x35":201,"0x36":1,"0x37":254,"0x38":201},"ports":{"P1":169}}},{"setup":{"iram":{"0x30":1,"0x31":2,"0x32":0,"0x33":3,"0x34":1,"0x35":2,"0x36":0,"0x37":3,"0x38":1}},"expect":{"iram":{"0x30":1,"0x31":2,"0x32":0,"0x33":3,"0x34":1,"0x35":2,"0x36":0,"0x37":3,"0x38":2},"ports":{"P1":170}}}],"maxCyc":40,"maxBytes":52},"hints":["Trải vòng lặp: 8 đoạn giống nhau, mỗi đoạn dùng địa chỉ trực tiếp 30H, 31H… thay cho @R0.","Giữ đếm trong A suốt tick. CJNE A,30H,$+3 nhảy tới ngay lệnh sau dù bằng hay khác, nên chỉ còn tác dụng đặt C = 1 khi A &lt; [30H] — và không đổi A.","Gom kết quả 8 kênh trong một byte có địa chỉ bit rồi ghi ra cổng một lần: mọi kênh đổi cùng lúc."],"why":"Mỗi kênh còn 4 chu kỳ (CJNE 2 + MOV bit,C 2) thay vì khoảng 9 chu kỳ trong vòng lặp; tổng 1 + 32 + 2 + 1 + 2 = 38 chu kỳ, 49 byte. Ghi P1 một lần ở cuối còn tránh “gai” ở các kênh: mọi kênh đổi mức trong cùng một lệnh. Thời gian tick ngắn trực tiếp giảm tải CPU: tick 38 chu kỳ trong khoảng 100 chu kỳ là 38 %, so với 80 % của code mẫu (80 chu kỳ)."}]);

makeQuiz("quiz47","score47",[{"q": "PWM phần mềm: mỗi tick 10 µs, 50 mức duty (N = 50). Tần số PWM là bao nhiêu?", "o": ["100 kHz", "20 kHz", "2 kHz", "500 Hz"], "a": 2, "e": "T = N × T_tick = 50 × 10 µs = 500 µs → f = 2 kHz. 100 kHz là tần số tick, không phải tần số PWM."}, {"q": "Đầu ra PWM tính bằng: A = đếm, CLR C, SUBB A,R4 (R4 = duty), MOV P2.0,C. Khi đếm = duty thì EN bằng?", "o": ["1, vì đếm bằng duty", "Không xác định", "1, vì SUBB luôn đặt C", "0, vì đếm − duty = 0 không mượn nên C = 0"], "a": 3, "e": "C = 1 chỉ khi đếm < duty (phép trừ phải mượn). Đếm = duty cho C = 0 nên duty 0 không bao giờ bật, duty N luôn bật."}, {"q": "Chương trình ngắt PWM dài 25 chu kỳ máy (kể cả lệnh gọi do phần cứng và RETI), ngắt mỗi 125 chu kỳ. Tải CPU là?", "o": ["25 %", "20 %", "80 %", "5 %"], "a": 1, "e": "25 / 125 = 0,2 = 20 %. Vòng chính còn 80 % thời gian."}, {"q": "Vì sao thêm MUL AB vào vòng chính làm chu kỳ PWM tạo trong ngắt timer bị rung (jitter)?", "o": ["CPU chỉ vào ngắt khi lệnh đang chạy xong; MUL dài 4 chu kỳ nên độ trễ đáp ứng ngắt thay đổi nhiều hơn", "MUL làm timer đếm chậm lại", "MUL xóa cờ TF0", "MUL đổi giá trị TH0"], "a": 0, "e": "Timer vẫn tràn đều (tự nạp bằng phần cứng); chỉ thời điểm chương trình ngắt ghi chân EN lệch theo lệnh đang chạy lúc tràn."}, {"q": "Ngay sau reset, P2 = FFH; driver nối EN = P2.0, IN1 = P2.1, IN2 = P2.2. Lệnh nên đặt đầu tiên là?", "o": ["SETB P2.1 — chọn chiều thuận", "MOV P2,#00H — xóa cả cổng", "Không cần, IN1 = IN2 đã là dừng", "CLR P2.0 — tắt EN trước khi chọn chiều"], "a": 3, "e": "Tắt EN trước mọi thứ là trạng thái an toàn và chỉ đổi đúng một chân. MOV P2,#00H làm đổi cả các chân khác trên P2."}]);

